// Applies the SQL migrations in ./drizzle (committed, generated by `npm run db:generate`).
// Runs on container start before the server; safe to run from several instances at once.
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import pg from "pg";

const url = process.env.DATABASE_URL;
if (!url) {
  console.error("[migrate] DATABASE_URL is required");
  process.exit(1);
}
const folder = process.env.MIGRATIONS_DIR || "./drizzle";
const newClient = () =>
  new pg.Client({
    connectionString: url,
    ssl: process.env.DATABASE_SSL === "true" ? { rejectUnauthorized: false } : undefined,
  });

// The database may still be starting (compose / platform cold start): retry for ~60s.
// A pg.Client cannot be reused after a failed connect, so each attempt gets a fresh one.
let client;
let lastErr;
for (let i = 0; i < 30; i++) {
  const c = newClient();
  try {
    await c.connect();
    client = c;
    lastErr = undefined;
    break;
  } catch (e) {
    lastErr = e;
    await c.end().catch(() => undefined);
    console.log(`[migrate] waiting for database (${i + 1}/30): ${e.message}`);
    await new Promise((r) => setTimeout(r, 2000));
  }
}
if (!client) {
  console.error("[migrate] could not connect:", lastErr?.message);
  process.exit(1);
}

try {
  await client.query("select pg_advisory_lock(727274)"); // serialize concurrent starters
  await migrate(drizzle(client), { migrationsFolder: folder });
  console.log("[migrate] migrations applied");
} catch (e) {
  console.error("[migrate] failed:", e);
  process.exitCode = 1;
} finally {
  await client.query("select pg_advisory_unlock(727274)").catch(() => undefined);
  await client.end();
}
